## Testing Modules Systematically

### The Module

```xiom
mod calculator {
  pub fn add(a: Int, b: Int) -> Int { a + b }
  pub fn divide(a: Int, b: Int) -> Option[Int] {
    if b == 0 { return Option.None; };
    Option.Some(a / b)
  }
  pub fn power(base: Int, exp: Int) -> Int {
    let mut result = 1;
    let mut i = 0;
    while i < exp { result *= base; i += 1; };
    result
  }
}
```

### Test Suite

```xiom
fn test_add() -> Bool {
  use calculator;
  assert(calculator.add(2, 3) == 5);
  assert(calculator.add(0, 0) == 0);
  assert(calculator.add(-1, 1) == 0);
  true
}

fn test_divide() -> Bool {
  use calculator;
  assert(calculator.divide(10, 2).unwrap() == 5);
  assert(calculator.divide(10, 0).is_none());
  assert(calculator.divide(0, 5).unwrap() == 0);
  true
}

fn test_power() -> Bool {
  use calculator;
  assert(calculator.power(2, 3) == 8);
  assert(calculator.power(5, 0) == 1);
  assert(calculator.power(1, 100) == 1);
  true
}
```

### Running All Tests

```xiom
fn main() -> Int {
  let mut passed = 0;
  if test_add() { passed += 1; };
  if test_divide() { passed += 1; };
  if test_power() { passed += 1; };
  io.println(passed);
  return 0;
}
```

