use xiom.io;
module geometry {
  pub fn area_rectangle(w: Int, h: Int) -> Int { w * h }
  pub fn perimeter_rectangle(w: Int, h: Int) -> Int { 2 * (w + h) }
  pub fn is_square(w: Int, h: Int) -> Bool { w == h }
}

fn test_geometry() -> Bool {
  assert(geometry.area_rectangle(4, 5) == 20);
  assert(geometry.perimeter_rectangle(4, 5) == 18);
  assert(geometry.is_square(4, 4) == true);
  assert(geometry.is_square(4, 5) == false);
  true
}

fn main() -> Int {
  if test_geometry() { io.println("Passed!"); };
  return 0;
}
